  THUMB.up_regador = thumb('k_bucket'); THUMB.up_vara = emojiThumb('🎣'); THUMB.up_espada = thumb('#sword'); THUMB.s_bolinho = emojiThumb('🧁'); THUMB.s_suco = emojiThumb('🧃');
