  THUMB.t_espada = icon(SWORDS[(S.gear && S.gear.sword) || 0].ic); THUMB.t_regador = icon('can'); THUMB.t_vara = icon('rod'); THUMB.t_picareta = icon('pick'); THUMB.t_machado = icon('axe'); THUMB.t_regador = icon('can'); THUMB.t_vara = icon('rod');
