  for (let y = PASTO.y0; y <= PASTO.y1; y++) for (const x of [PASTO.x0 - 1, PASTO.x1 + 1]) if (!(x === PASTO.x1 + 1 && (y === 42 || y === 43))) fencePiece(pastoFence, x, y, false);
