    const fz = y + 3.75; for (let i = 0; i <= 8; i++) { const p = new THREE.Mesh(new THREE.BoxGeometry(0.07, 0.45, 0.07), postM); p.position.set(x + i * 0.5, 0.22, fz); world.add(p); }
