    for (let i = 0; i < 6; i++) { const f = cloneM(i % 3 ? 'q_flower_r' : 'q_flower_y'); f.position.set(x + 0.3 + i * 0.65, 0, y + 3.35); f.scale.multiplyScalar(0.8); world.add(f); }
