function fogWrite() { const d = FOGR.data, c = FOGR.cur; for (let i = 0; i < W * H; i++) { const v = Math.round(clamp(c[i], 0, 1) * 255); d[i * 4] = v; d[i * 4 + 3] = 255; } FOGR.tex.needsUpdate = true; }
