  for (let i = 0; i < 4; i++) { const pl = new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.62, 0.02), dark); pl.position.set(-0.71 + i * 0.47, 0.4, 0.76); g.add(pl); }
