  const set = (v) => { S.house = S.house || {}; S.house.roof = v; applyFacade(); sfx('accept'); burst(H1.x + 2, 3.5, H1.y + 1.6, ['#ffe18d', '#ffffff', '#ffb3c8'], 30, 3, true, true); openFacade(); };
