  if (!PVP.on) return; if (mode !== 'out' || !MP.code) { pvpLeave(); return; }
  const dc = Math.hypot(P.x - PVP.cx, P.z - PVP.cz); if (dc > PVP.R - 0.35) { const k = (PVP.R - 0.35) / dc; P.x = PVP.cx + (P.x - PVP.cx) * k; P.z = PVP.cz + (P.z - PVP.cz) * k; }
