    if (player) { player.obj.position.set(P.x - Math.sin(SEA.boat.rotation.y) * 0.55, 0.74 + Math.sin(gtime * 2) * 0.05, P.z - Math.cos(SEA.boat.rotation.y) * 0.55); player.obj.rotation.y = SEA.boat.rotation.y; }
