  if (pat === 'estrelas') for (const [x, y] of [[4, 4], [12, 11]]) { for (const [dx, dy] of [[0, -1], [-1, 0], [0, 0], [1, 0], [0, 1]]) px(x + dx, y + dy, '#fff6c8'); px(x - 2, y, '#ffe18d'); px(x + 2, y, '#ffe18d'); px(x, y - 2, '#ffe18d'); px(x, y + 2, '#ffe18d'); }
