      if (k === 'kn_lantern') { const l = new THREE.PointLight(0xffc477, 0, 7, 1.6); l.position.set(x + 0.5, 1.3, y + 0.5); world.add(l); lampLights.push(l); HOMEP.objs.push(l); }
