const ARROWS = [], arrowGeo = new THREE.CylinderGeometry(0.025, 0.025, 0.7, 5).rotateX(Math.PI / 2), arrowMat = new THREE.MeshLambertMaterial({ color: '#f4e4c8', emissive: '#ffe18d', emissiveIntensity: 0.4 });
