    if (a.mine) for (const c of Object.values(MP.chars)) if (c && c.obj.visible && Math.hypot(c.x - a.x, c.z - a.z) < 0.55) { hit = true; burst(a.x, 1, a.z, ['#ffffff', '#ffe18d'], 8, 2); sfx('hit'); hitStop = 0.05; }
